import re, subprocess, random, sys

UNCOUNTABLE = {"equipment","information","rice","money","species","series","fish","sheep","jeans","police"}

def pluralize(w):
    return w if w in UNCOUNTABLE else w + "s"

RULES = [
    (re.compile(r'((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$'),
     lambda m: m.group(1) + (m.group(2) or '') + 'sis'),
    (re.compile(r'([^aeiouy]|qu)ies$'), lambda m: m.group(1) + 'y'),
    (re.compile(r'([^f])ves$'), lambda m: m.group(1) + 'fe'),
    (re.compile(r'([m|l])ice$'), lambda m: m.group(1) + 'ouse'),
    (re.compile(r'([ti])a$'), lambda m: m.group(1) + 'um'),
    (re.compile(r'(alias|status)es$'), lambda m: m.group(1)),
    (re.compile(r'(bus)es$'), lambda m: m.group(1)),
    (re.compile(r'(cris|ax|test)es$'), lambda m: m.group(1) + 'is'),
    (re.compile(r'(matr)ices$'), lambda m: m.group(1) + 'ix'),
    (re.compile(r'(n)ews$'), lambda m: m.group(1) + 'ews'),
    (re.compile(r'(o)es$'), lambda m: m.group(1)),
    (re.compile(r'(octop|vir)i$'), lambda m: m.group(1) + 'us'),
    (re.compile(r'(quiz)zes$'), lambda m: m.group(1)),
    (re.compile(r'(vert|ind)ices$'), lambda m: m.group(1) + 'ex'),
    (re.compile(r'(x|ch|ss|sh)es$'), lambda m: m.group(1)),
    (re.compile(r's$'), lambda m: ''),
    (re.compile(r'^(ox)en$'), lambda m: m.group(1)),
]

def singularize(w):
    if w in UNCOUNTABLE:
        return w
    for pat, rep in RULES:
        m = pat.search(w)
        if m:
            return w[:m.start()] + rep(m) + w[m.end():]
    return w

def camelize(w):
    out = []
    cap = True
    for c in w:
        if c == '_':
            cap = True
            continue
        out.append(c.upper() if cap else c)
        cap = False
    return ''.join(out)

def underscore(w):
    out = []
    for i, c in enumerate(w):
        if 'A' <= c <= 'Z':
            if i > 0:
                out.append('_')
            out.append(c.lower())
        else:
            out.append(c)
    return ''.join(out)

def classify(w):
    return camelize(singularize(w))

def tableize(w):
    return pluralize(underscore(w))

def isPlural(w):
    return '1' if singularize(w) != w else '0'

def isSingular(w):
    return '1' if singularize(w) == w else '0'

def expected(w):
    return (pluralize(w), singularize(w), classify(w), tableize(w), isPlural(w), isSingular(w))

def actual(w):
    out = subprocess.run(['/workspace/dataset/test20_executable', w], capture_output=True, text=True).stdout.split('\n')
    return (out[0], out[1], out[5], out[6], out[18], out[19])

random.seed(42)
words = []
# targeted endings
endings = ['s','es','ses','sses','ies','ves','fes','oes','xes','ches','shes','zes','ice','a','ia','ta','i','en','um','us','is','os','ss','zzes','eis','ys','ays','eys','oys','asis','esis','isis','aris','eris']
stems = ['','a','ab','foo','bar','x','qu','the','ban','cat','dog','matr','vert','ind','octop','vir','cris','ax','test','quiz','bus','alias','status','mo','lo','kni','o','ox','The','Foo','B','QU']
for s in stems:
    for e in endings:
        words.append(s+e)
# random words
alphabet = 'abcdefghijklmnoprstuvxyzSEF_/-19|'
for _ in range(400):
    n = random.randint(1,10)
    words.append(''.join(random.choice(alphabet) for _ in range(n)))
# uncountable-ish
words += list(UNCOUNTABLE) + ['news','sms','deer','moose','sheepS',' fis','fishy','fishing','sheepish','specie','serie','moneyS','Money','FISH','Fish','policemen','equipmente']

bad = 0
for w in set(words):
    if w == '':
        continue
    try:
        e = expected(w)
        a = actual(w)
    except Exception as ex:
        print('ERROR', repr(w), ex); bad += 1; continue
    if e != a:
        bad += 1
        print('MISMATCH', repr(w), 'expected', e, 'actual', a)
        if bad > 30: sys.exit(1)
print('DONE, mismatches:', bad, 'total words:', len(set(words)))
EOF
